package com.bank.report;

import java.util.logging.*;

public class ConcatDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatementGenerator gen = new StatementGenerator();
        int lines = 20_000;

        long t1 = System.nanoTime();
        String slow = gen.slowConcat("SAV2001", lines);
        long slowMs = (System.nanoTime() - t1) / 1_000_000;

        long t2 = System.nanoTime();
        String fast = gen.fastConcat("SAV2001", lines);
        long fastMs = (System.nanoTime() - t2) / 1_000_000;

        log.warning(() -> "slow (+ in loop) ms = " + slowMs + ", length=" + slow.length());
        log.info(() -> "fast (StringBuilder) ms = " + fastMs + ", length=" + fast.length());
        log.info(() -> "same content: " + slow.equals(fast));
    }
}

