class StatementGenerator {
    // Compile-time constant folding: this is ONE literal, no runtime concat.
    private static final String HEADER = "National" + " Bank" + " of India";

    // BAD: + in a loop -> quadratic time + heavy garbage (new String each iter).
    String slowConcat(String accountId, int lines) {
        String result = HEADER + " - Statement for " + accountId + "\n";
        for (int i = 0; i < lines; i++) {
            result = result + "Line " + i + ": TXN amount 100\n"; // rebuilds whole string
        }
        return result;
    }

    // GOOD: single StringBuilder outside the loop -> linear time, low garbage.
    String fastConcat(String accountId, int lines) {
        // pre-size capacity to avoid internal array resizes
        StringBuilder sb = new StringBuilder(lines * 32);
        sb.append(HEADER).append(" - Statement for ").append(accountId).append("\n");
        for (int i = 0; i < lines; i++) {
            sb.append("Line ").append(i).append(": TXN amount 100\n"); // append in place
        }
        return sb.toString();
    }
}
